mkdir -p /app/output && cat > /app/output/styles.css << 'EOF'
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700;800&family=Inter:wght@300;400;500;600&display=swap');

:root {
  --bg: #f5f2ed;
  --bg-soft: #eee8df;
  --text: #1a1a1a;
  --muted: #5c554c;
  --accent-terracotta: #b8745f;
  --accent-sage: #9fae9a;
  --accent-sand: #c8b59a;
  --line: #d9d2c8;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

.page {
  min-height: 100vh;
  padding: 1.75rem 2rem 4rem;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3.5rem;
}

.brand {
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.nav {
  display: flex;
  gap: 1.4rem;
  align-items: center;
}

.nav a {
  font-size: 0.86rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  opacity: 0.9;
}

.nav a:hover,
.nav a.active { opacity: 1; text-decoration: underline; text-underline-offset: 0.3rem; }

.menu-btn {
  display: none;
  border: 0;
  background: transparent;
  color: var(--text);
  width: 2.4rem;
  height: 2.4rem;
  cursor: pointer;
  padding: 0;
}

.menu-btn span,
.menu-btn::before,
.menu-btn::after {
  content: "";
  display: block;
  height: 2px;
  background: var(--text);
  margin: 6px 0;
  transition: 0.25s ease;
}

.menu-btn.open span { opacity: 0; }
.menu-btn.open::before { transform: translateY(8px) rotate(45deg); }
.menu-btn.open::after { transform: translateY(-8px) rotate(-45deg); }

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: rgba(245, 242, 237, 0.98);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 40;
}

.mobile-overlay.open { display: flex; }

.mobile-nav {
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
  text-align: center;
}

.mobile-nav a {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 8vw, 3.5rem);
}

.hero-kicker {
  font-size: 0.76rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 1rem;
}

.editorial-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2.4rem, 8vw, 6.5rem);
  line-height: 0.95;
  margin: 0;
  letter-spacing: -0.02em;
}

.lead {
  max-width: 52ch;
  font-size: 1.08rem;
  line-height: 1.75;
  color: #2f2b28;
}

.home-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 4rem;
  align-items: end;
  margin-bottom: 5rem;
}

.media-blocks {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  align-self: stretch;
}

.block {
  border-radius: 2px;
  min-height: 200px;
}

.block.tall { min-height: 330px; }
.block.terracotta { background: linear-gradient(140deg, #c78570, #ab6f5b); }
.block.sage { background: linear-gradient(140deg, #b2beb0, #95a390); }
.block.sand { background: linear-gradient(140deg, #d5c4ad, #bca88e); }

.section {
  margin: 6rem 0;
}

.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.9rem, 5vw, 3.4rem);
  margin: 0 0 1.4rem;
}

.divider { border: 0; border-top: 1px solid var(--line); margin: 4rem 0; }

.marquee-wrap { overflow: hidden; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }

.marquee-row {
  display: flex;
  width: max-content;
  gap: 2.2rem;
  padding: 1.1rem 0;
  white-space: nowrap;
  will-change: transform;
}

.marquee-row span {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.2rem, 2.8vw, 2.2rem);
  letter-spacing: 0.02em;
}

@keyframes marquee-left { from { transform: translate3d(0,0,0);} to { transform: translate3d(-50%,0,0);} }
@keyframes marquee-right { from { transform: translate3d(-50%,0,0);} to { transform: translate3d(0,0,0);} }

.row-left { animation: marquee-left 26s linear infinite; }
.row-right { animation: marquee-right 30s linear infinite; }

.about {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  max-width: 1100px;
}

.letter {
  max-width: 760px;
  margin: 0 auto;
}

.letter .editorial-title { margin-bottom: 2rem; }

.letter p {
  font-size: 1.08rem;
  line-height: 1.95;
  color: #2e2a25;
  margin: 0 0 1.35rem;
}

.letter .signature {
  margin-top: 2.5rem;
  font-family: 'Playfair Display', serif;
  font-size: 1.5rem;
}

.services-grid,
.clients-grid {
  display: grid;
  gap: 1.7rem 2rem;
}

.services-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.clients-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }

.card {
  padding: 1rem 0;
  border-top: 1px solid var(--line);
}

.card h3 {
  margin: 0 0 0.45rem;
  font-family: 'Playfair Display', serif;
  font-size: 1.6rem;
}

.card p { margin: 0; color: #3a342f; line-height: 1.65; }

.contact-hero {
  min-height: 62vh;
  display: grid;
  align-content: center;
  justify-items: center;
  text-align: center;
}

.contact-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(4.5rem, 21vw, 14rem);
  line-height: 0.9;
  letter-spacing: -0.03em;
  margin: 0;
}

.contact-links {
  display: flex;
  gap: 1.2rem;
  font-size: 1.1rem;
  margin-top: 1.2rem;
}

.contact-links a:hover { text-decoration: underline; text-underline-offset: 0.25rem; }

@media (max-width: 960px) {
  .home-grid,
  .about,
  .services-grid,
  .clients-grid { grid-template-columns: 1fr; }
  .media-blocks { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 760px) {
  .page { padding: 1.2rem 1.1rem 3rem; }
  .nav { display: none; }
  .menu-btn { display: block; position: relative; z-index: 50; }
  .lead { font-size: 1rem; }
  .contact-links { flex-direction: column; gap: 0.5rem; }
}
EOF

cat > /app/output/script.js << 'EOF'
(function () {
  const menuBtn = document.querySelector('[data-menu-btn]');
  const overlay = document.querySelector('[data-mobile-overlay]');

  if (menuBtn && overlay) {
    const toggle = () => {
      const open = menuBtn.classList.toggle('open');
      overlay.classList.toggle('open', open);
      menuBtn.setAttribute('aria-expanded', String(open));
      document.body.style.overflow = open ? 'hidden' : '';
    };

    menuBtn.addEventListener('click', toggle);
    overlay.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => {
        menuBtn.classList.remove('open');
        overlay.classList.remove('open');
        menuBtn.setAttribute('aria-expanded', 'false');
        document.body.style.overflow = '';
      });
    });
  }
})();
EOF

